const setPersonalTokensAllowed = `-- name: SetPersonalTokensAllowed :exec
INSERT INTO org_token_settings (org_id, personal_tokens_allowed, updated_at) VALUES ($1, $2, now())
ON CONFLICT (org_id) DO UPDATE SET personal_tokens_allowed = EXCLUDED.personal_tokens_allowed, updated_at = now()
`

type SetPersonalTokensAllowedParams struct {
	OrgID                 uuid.UUID `json:"org_id"`
	PersonalTokensAllowed bool      `json:"personal_tokens_allowed"`
}

func (q *Queries) SetPersonalTokensAllowed(ctx context.Context, arg SetPersonalTokensAllowedParams) error {
	_, err := q.db.Exec(ctx, setPersonalTokensAllowed, arg.OrgID, arg.PersonalTokensAllowed)
	return err
}

const touchPersonalToken = `-- name: TouchPersonalToken :exec
UPDATE personal_tokens SET last_used_at = now()
WHERE id = $1 AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')
`

// At most one write per minute per token, decided and stamped by the
// database's own now() (TouchAPIToken's throttle, without a Go timestamp).
func (q *Queries) TouchPersonalToken(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, touchPersonalToken, id)
	return err
}

const touchPersonalTokenGrant = `-- name: TouchPersonalTokenGrant :exec
UPDATE personal_token_grants SET last_used_at = now()
WHERE token_id = $1 AND org_id = $2 AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')
`

type TouchPersonalTokenGrantParams struct {
	TokenID uuid.UUID `json:"token_id"`
	OrgID   uuid.UUID `json:"org_id"`
}

// TouchPersonalToken's throttle for one grant.
func (q *Queries) TouchPersonalTokenGrant(ctx context.Context, arg TouchPersonalTokenGrantParams) error {
	_, err := q.db.Exec(ctx, touchPersonalTokenGrant, arg.TokenID, arg.OrgID)
	return err
}

const unblockPersonalTokenOwner = `-- name: UnblockPersonalTokenOwner :execrows
DELETE FROM personal_token_grants WHERE org_id = $1 AND user_id = $2 AND blocked_at IS NOT NULL
`

type UnblockPersonalTokenOwnerParams struct {
	OrgID  uuid.UUID `json:"org_id"`
	UserID uuid.UUID `json:"user_id"`
}

// Lifting the block deletes every blocked grant of the user in the
// organization: the owner may add the organization again.
func (q *Queries) UnblockPersonalTokenOwner(ctx context.Context, arg UnblockPersonalTokenOwnerParams) (int64, error) {
	result, err := q.db.Exec(ctx, unblockPersonalTokenOwner, arg.OrgID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updatePersonalToken = `-- name: UpdatePersonalToken :one
UPDATE personal_tokens SET name = $3, areas = $5::text[], expires_at = $4
WHERE id = $1 AND user_id = $2 AND revoked_at IS NULL
RETURNING id, user_id, name, kind, areas, expires_at, last_used_at, created_at
`

type UpdatePersonalTokenParams struct {
	ID        uuid.UUID          `json:"id"`
	UserID    uuid.UUID          `json:"user_id"`
	Name      string             `json:"name"`
	ExpiresAt pgtype.Timestamptz `json:"expires_at"`
	Areas     []string           `json:"areas"`
}

type UpdatePersonalTokenRow struct {
	ID         uuid.UUID          `json:"id"`
	UserID     uuid.UUID          `json:"user_id"`
	Name       string             `json:"name"`
	Kind       string             `json:"kind"`
	Areas      []string           `json:"areas"`
	ExpiresAt  pgtype.Timestamptz `json:"expires_at"`
	LastUsedAt pgtype.Timestamptz `json:"last_used_at"`
	CreatedAt  time.Time          `json:"created_at"`
}

func (q *Queries) UpdatePersonalToken(ctx context.Context, arg UpdatePersonalTokenParams) (UpdatePersonalTokenRow, error) {
	row := q.db.QueryRow(ctx, updatePersonalToken,
		arg.ID,
		arg.UserID,
		arg.Name,
		arg.ExpiresAt,
		arg.Areas,
	)
	var i UpdatePersonalTokenRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Name,
		&i.Kind,
		&i.Areas,
		&i.ExpiresAt,
		&i.LastUsedAt,
		&i.CreatedAt,
	)
	return i, err
}
